package httpapi

import (
	"io/fs"
	"mime"
	"net/http"
	"path"
	"strings"
)

// spa serves the embedded admin build with history-mode fallback (S13 §8): hashed assets are cached for a
// year, index.html and version.json are never cached, unknown paths return index.html.
func (s *Server) spa() http.Handler {
	// The PWA manifest (generated by pwa-generator) is not in Go's built-in type table.
	_ = mime.AddExtensionType(".webmanifest", "application/manifest+json")
	files := http.FileServerFS(s.o.SPA)
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		p := strings.TrimPrefix(path.Clean("/"+r.URL.Path), "/")
		if p == "" {
			p = "index.html"
		}
		if st, err := fs.Stat(s.o.SPA, p); err != nil || st.IsDir() {
			p = "index.html"
		}
		switch {
		case p == "index.html" || p == "version.json":
			w.Header().Set("Cache-Control", "no-cache")
		case strings.HasPrefix(p, "assets/"):
			w.Header().Set("Cache-Control", "public, max-age=31536000, immutable")
		default:
			w.Header().Set("Cache-Control", "public, max-age=3600")
		}
		r2 := r.Clone(r.Context())
		r2.URL.Path = "/" + p
		if p == "index.html" {
			r2.URL.Path = "/"
		}
		files.ServeHTTP(w, r2)
	})
}
